        /// <summary>
        /// Get the visit status of a patient
        /// </summary>
        /// <param name="objPatientsInfo">Patient object is used to retrieve data</param>
        public void GetVisitStatus(MEPatientsInfo objPatientsInfo)
        {
            DbCommand cmd = dal.GetStoredProcedureCommand("MEPatients_GetVisitStatus");
            dal.AddParameter(cmd, "MEPatientID", DbType.Int32, ParameterDirection.Input, objPatientsInfo.MEPatientID);
            dal.AddParameter(cmd, "OrderCount", DbType.Int32, ParameterDirection.Output, objPatientsInfo.OrderCount);
            dal.AddParameter(cmd, "MedicationCount", DbType.Int32, ParameterDirection.Output, objPatientsInfo.MedicationCount);
            dal.AddParameter(cmd, "VitalSignCount", DbType.Int32, ParameterDirection.Output, objPatientsInfo.VitalSignCount);
            dal.AddParameter(cmd, "RecentLabCount", DbType.Int32, ParameterDirection.Output, objPatientsInfo.RecentLabCount);
            dal.AddParameter(cmd, "LabTableCount", DbType.Int32, ParameterDirection.Output, objPatientsInfo.LabTableCount);
            dal.GetDataSet(cmd);
            objPatientsInfo.OrderCount = Convert.ToInt32(dal.GetParameterValue(cmd, "OrderCount"));
            objPatientsInfo.MedicationCount = Convert.ToInt32(dal.GetParameterValue(cmd, "MedicationCount"));
            objPatientsInfo.VitalSignCount = Convert.ToInt32(dal.GetParameterValue(cmd, "VitalSignCount"));
            objPatientsInfo.RecentLabCount = Convert.ToInt32(dal.GetParameterValue(cmd, "RecentLabCount"));
            objPatientsInfo.LabTableCount = Convert.ToInt32(dal.GetParameterValue(cmd, "LabTableCount"));
        }

