        /// <summary>
        /// Get the full address from some address fields
        /// </summary>
        /// <param name="objPatientsInfo"></param>
        /// <returns></returns>
        public string GetFullAddress(MEPatientsInfo objPatientsInfo)
        {
            string address = string.Empty;
            if (!string.IsNullOrEmpty(objPatientsInfo.MEPatientContactAddressLine1))
            {
                address += objPatientsInfo.MEPatientContactAddressLine1 + ", ";
            }
            if (!string.IsNullOrEmpty(objPatientsInfo.MEPatientContactAddressWard))
            {
                address += objPatientsInfo.MEPatientContactAddressWard + ", ";
            }
            if (!string.IsNullOrEmpty(objPatientsInfo.MEPatientContactAddressDistrict))
            {
                address += objPatientsInfo.MEPatientContactAddressDistrict + ", ";
            }
            if (!string.IsNullOrEmpty(objPatientsInfo.MEPatientContactAddressStateProvince))
            {
                address += objPatientsInfo.MEPatientContactAddressStateProvince + ", ";
            }
            if (!string.IsNullOrEmpty(objPatientsInfo.MEPatientContactAddressCountry))
            {
                address += objPatientsInfo.MEPatientContactAddressCountry + ", ";
            }
            if (!string.IsNullOrEmpty(address))
                address = address.Substring(0, address.Length - 2);
            return address;
        }

