        /// <summary>
        /// uthv
        /// 18032017
        /// Tao moi customer tu thong tin patient
        /// Dung trong truong hop dong bo du lieu tu bs24x7 xuong
        /// </summary>
        /// <param name="objPatientsInfo"></param>
        /// <returns></returns>
        public int CreateCustomerFromPatientInfo(MEPatientsInfo objPatientsInfo, int branchId)
        {
            var customerInfo = new ARCustomersInfo
            {
                FK_BRBranchID = branchId,
                ARCustomerName = objPatientsInfo.MEPatientName,
                ARCustomerActiveCheck = true,
                ARCustomerTypeCombo = "Patient",
                ARCustomerContactBirthday = objPatientsInfo.MEPatientBirthday,
                ARCustomerContactEmail1 = objPatientsInfo.MEPatientContactEmail,
                ARCustomerContactPhone = objPatientsInfo.MEPatientContactPhone,
                ARCustomerContactCellPhone = objPatientsInfo.MEPatientContactCellPhone,
                ARCustomerContactAddressLine1 = objPatientsInfo.MEPatientContactAddressLine1,
                ARCustomerContactTitle = objPatientsInfo.MEPatientTitle,
                MEPatientIDCard = objPatientsInfo.MEPatientIDCard,
                ARCustomerContactAddressCity = objPatientsInfo.MEPatientContactAddressCity,
                ARCustomerContactFirstName = objPatientsInfo.MEPatientFirstName,
                ARCustomerContactLastName = objPatientsInfo.MEPatientLastName,
                ARCustomerContactName = objPatientsInfo.MEPatientName,
                ARCustomerName1 = objPatientsInfo.MEPatientName,
                // UtHV Patient and Customer must the same NO
                ARCustomerNo = objPatientsInfo.MEPatientNo
            };
            var customersController = new ARCustomersController();

            customersController.CreateObject(customerInfo);
            return customerInfo.ARCustomerID;
        }

